cards.solution:
class Karyawan {
  constructor(public nama: string, protected gajiPokok: number) {}
  gaji(): number {
    return this.gajiPokok;
  }
}
class Manajer extends Karyawan {
  constructor(nama: string, gajiPokok: number, private tunjangan: number) {
    super(nama, gajiPokok);
  }
  override gaji(): number {
    return super.gaji() + this.tunjangan;
  }
}
const semua: Karyawan[] = [new Karyawan("Sari", 5000000), new Manajer("Dodi", 8000000, 2000000)];
for (const k of semua) console.log(k.nama, k.gaji());
